// Task #732 / #755 — background job + concurrency guard for POST /admin/dm-blast.
// A blast sends up to 500 DMs sequentially at 700 ms each (~6 min). Holding the
// HTTP request open that long risks a proxy timeout, so the send now runs as an
// in-process background job: POST kicks it off and returns a job id immediately,
// and the AdminPanel polls a status endpoint for live progress. The single
// `_dmBlastJob` slot doubles as the concurrency guard from Task #732 — a second
// request fails fast with a 409 while a job is still running (`done === false`).
// The finished job is kept in the slot so the status poll can read the final
// per-recipient breakdown; the next POST overwrites it once the prior one is done.
// In-process is sufficient: the prod web server is a single PM2 process per
// edition, and the job is marked done in a finally so a thrown send can't wedge it.
let _dmBlastJob = null; // null until first blast, then the latest job object (see runner)
let _dmBlastJobSeq = 0;

// Task #381 — Expo push fan-out. Posts up to 100 messages per HTTP call
// to Expo's push service (no SDK needed; thin wrapper around node-fetch).
// Returns { sent, removed } where `removed` counts tokens we deleted
// because Expo reported them as DeviceNotRegistered or InvalidCredentials.
// `messages` is an array of { to, title, body, data?, sound? } objects.
async function _sendExpoPush(messages) {
  if (!Array.isArray(messages) || !messages.length) return { sent: 0, removed: 0 };
  let _ops = null; try { _ops = require('./opsState'); } catch (_) {}
  const fetch = require('node-fetch');
  let sent = 0;
  let removed = 0;
  // Expo accepts up to 100 messages per batch.
  for (let i = 0; i < messages.length; i += 100) {
    const batch = messages.slice(i, i + 100);
    try {
      const r = await fetch('https://exp.host/--/api/v2/push/send', {
        method: 'POST',
        headers: {
          'Accept': 'application/json',
          'Accept-Encoding': 'gzip, deflate',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(batch),
      });
      const json = await r.json().catch(() => ({}));
      const tickets = Array.isArray(json?.data) ? json.data : [];
      if (_ops) _ops.reportPush({ delivered: true, error: null });
      let _batchOk = 0, _batchRemoved = 0;
      for (let j = 0; j < tickets.length; j++) {
        const t = tickets[j];
        const token = batch[j]?.to;
        if (t?.status === 'ok') {
          sent++;
          _batchOk++;
          if (token) db.touchExpoPushToken(token).catch(() => {});
        } else if (t?.status === 'error') {
          const code = t?.details?.error;
          if (code === 'DeviceNotRegistered' || code === 'InvalidCredentials') {
            if (token) {
              await db.removeExpoPushToken(token).catch(() => {});
              removed++;
              _batchRemoved++;
            }
          }
        }
      }
      // Task #417 — push delivery counters per Expo batch.
      try {
        require('../observability/metrics').recordPushDelivery({
          channel: 'expo', sent: _batchOk, removed: _batchRemoved,
        });
      } catch (_) {}
    } catch (err) {
      console.warn('[ExpoPush] batch failed:', err?.message || err);
      if (_ops) _ops.reportPush({ error: err?.message || String(err) });
      try {
        require('../observability/metrics').recordPushDelivery({ channel: 'expo', failed: batch.length });
      } catch (_) {}
    }
  }
  return { sent, removed };
}

// Helper that combines the per-account preference gate + token lookup +
// fan-out. Mirrors the web-push iteration pattern in /me/push/test and
// /internal/inhouse/:id/imminent-push. Safe to call even when nobody has
// a token registered — returns 0/0 quickly.
async function _fanOutExpoPush(accountId, { title, body, url, data }) {
  const tokens = await db.getExpoPushTokensForAccount(accountId).catch(() => []);
  if (!tokens?.length) return { sent: 0, removed: 0 };
  const messages = tokens.map(t => ({
    to: t.token,
    title,
    body,
    sound: 'default',
    data: { ...(data || {}), url: url || '/' },
  }));
  return _sendExpoPush(messages);
}

