function _runStaleUploadReaper() {
  const now = Date.now();
  let reaped = 0;
  for (const [jobId, job] of uploadJobs) {
    const age = now - (job.startedAt || 0);
    if (age > STALE_JOB_TTL && (job.status === 'uploading' || job.status === 'assembling')) {
      console.log(`[API] Reaping stale job ${jobId} (status=${job.status}, age=${Math.round(age / 60000)}m)`);
      cleanupChunks(jobId);
      if (job.filePath) cleanupFile(job.filePath);
      uploadJobs.delete(jobId);
      reaped++;
    }
  }
  return { reaped, total: uploadJobs.size };
}
setInterval(_runStaleUploadReaper, 5 * 60 * 1000);

// Task #317 — finalise account-deletion requests once their 30-day grace
// window elapses. Runs once on boot (after a brief delay so DB init can
// complete) and then every 6 hours. Anonymizes each due account
// (persona_name → "Deleted Player #N", customisations cleared, match-history
// rows preserved). Best-effort; per-account failures are logged but do not
// halt the sweep.
async function _runAccountDeletionSweep() {
  try {
    const due = await db.listAccountsReadyForAnonymization(30);
    for (const accountId of due) {
      try {
        const result = await db.anonymizeAccount(accountId);
        // Belt-and-braces session cleanup at anonymization time too — the
        // request-time revoke should have caught these, but if a session
        // was created in the gap between request and grace expiry (e.g.
        // sign-in that *cancelled* deletion, then re-request) we want to
        // make absolutely sure no cookie survives the final purge.
        await db.revokeAllSessionsForAccount(accountId).catch(() => 0);
        if (!result?.already) {
          console.log('[Account Deletion] sweep anonymized', accountId, 'as', result?.label);
        }
      } catch (e) {
        console.warn('[Account Deletion] sweep failed for', accountId, '—', e?.message || e);
      }
    }
  } catch (e) {
    console.warn('[Account Deletion] sweep listing failed:', e?.message || e);
  }
}
setTimeout(() => { _runAccountDeletionSweep().catch(() => {}); }, 60_000).unref();
setInterval(() => { _runAccountDeletionSweep().catch(() => {}); }, 6 * 60 * 60 * 1000).unref();

// Task #408 — Smurf detector (advisory). Nightly recompute of heuristic
// scores for every active account. Also invoked on-demand from the admin
// panel via POST /api/admin/smurf-watch/recompute. Best-effort: per-account
// failures are logged but do not halt the sweep. Module-scope flag prevents
// the on-demand path from racing the nightly cron.
let _smurfRecomputeInFlight = false;
async function _runSmurfRecompute(reason = 'cron') {
  if (_smurfRecomputeInFlight) {
    console.log('[Smurf] recompute already in flight, skipping', reason);
    return { skipped: true };
  }
  _smurfRecomputeInFlight = true;
  const started = Date.now();
  try {
    const { recomputeAll } = require('../smurf/smurfScorer');
    const result = await recomputeAll(db.getPool());
    const ms = Date.now() - started;
    console.log(`[Smurf] ${reason} recompute done — scanned=${result.scanned} written=${result.written} in ${ms}ms`);
    try { await db.recordCronHeartbeat('smurf_recompute', { ok: true, scanned: result.scanned, written: result.written, ms }); } catch (_) {}
    return { ...result, ms };
  } catch (e) {
    console.warn('[Smurf] recompute failed:', e?.message || e);
    try { await db.recordCronHeartbeat('smurf_recompute', { ok: false, error: e?.message || String(e) }); } catch (_) {}
    throw e;
  } finally {
    _smurfRecomputeInFlight = false;
  }
}
// First run 5 min after boot to avoid stacking with other startup work,
// then daily.
setTimeout(() => { _runSmurfRecompute('boot').catch(() => {}); }, 5 * 60_000).unref();
setInterval(() => { _runSmurfRecompute('cron').catch(() => {}); }, 24 * 60 * 60 * 1000).unref();

// Task #419 — Bot-independent owner alert path. Used by the rollover cron
// when the Discord bot isn't around (or when bot._dmOwner itself throws) so
// failures are never silent. Tries, in order:
//   1. bot._dmOwner if the bot is connected (DMs OWNER_DISCORD_ID).
//   2. OWNER_ALERT_WEBHOOK_URL — POSTs a JSON body { text } to that URL.
//      Compatible with Discord/Slack-style incoming webhooks out of the box.
//   3. Loud stderr line tagged [ROLLOVER FAILURE] — guaranteed to land in
//      PM2 logs even when both 1 and 2 are unavailable, so the operator can
//      find it after the fact.
// Generic bot-independent owner alert. Tries, in order: bot._dmOwner (DMs
// OWNER_DISCORD_ID), then OWNER_ALERT_WEBHOOK_URL (Discord/Slack-style
// incoming webhook), then a loud stderr line so the alert is always
// discoverable in PM2 logs. Returns whether a channel actually delivered.
async function _alertOwner(text, { logTag = 'OWNER ALERT', bot } = {}) {
  const b = bot || getDiscordBot();
  let delivered = false;
  if (b && typeof b._dmOwner === 'function') {
    try { await b._dmOwner(text); delivered = true; } catch (_) {}
  }
  if (!delivered && process.env.OWNER_ALERT_WEBHOOK_URL) {
    try {
      const fetchFn = global.fetch || (await import('node-fetch')).default;
      const r = await fetchFn(process.env.OWNER_ALERT_WEBHOOK_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text, content: text }),
      });
      if (r.ok) delivered = true;
    } catch (whErr) {
      console.warn('[OwnerAlert] OWNER_ALERT_WEBHOOK_URL post failed:', whErr.message);
    }
  }
  if (!delivered) {
    console.error(`[${logTag}] ${text} (owner-alert channels unavailable — log-only)`);
  }
  return delivered;
}

async function _alertOwnerOfRolloverFailure(season, err, bot) {
  const text =
    `🚨 [Auto-Rollover Failure] Season "${season.name}" (id=${season.id}): ` +
    `${err.message || String(err)}. Season remains active; the next per-minute ` +
    `cron tick will retry. Investigate before then.`;
  const delivered = await _alertOwner(text, { logTag: 'ROLLOVER FAILURE', bot });
  // Always also log loud so the rollover failure is discoverable even when a
  // channel delivered.
  if (delivered) console.error(`[ROLLOVER FAILURE] ${text}`);
}

// Task #419 — Season auto-rollover cron tick. Runs every minute, finds any
// seasons whose `end_date` is in the past + are still active + have no
// `season_archives` row, and triggers the bot's transactional rollover
// (snapshot → archive → mint achievements → activate next → announce). The
// in-flight flag prevents overlapping ticks; the underlying DB rollover is
// also idempotent. Owner-DM-on-failure happens inside _closeSeasonAndAnnounce.
let _seasonRolloverInFlight = false;
async function _runSeasonRolloverTick(reason = 'cron') {
  if (_seasonRolloverInFlight) return;
  _seasonRolloverInFlight = true;
  try {
    const due = await db.getSeasonsDueForRollover();
    if (!due.length) return;
    const bot = getDiscordBot();
    for (const season of due) {
      try {
        if (bot && typeof bot._closeSeasonAndAnnounce === 'function') {
          // Bot path: owner-DM-on-failure happens inside the bot helper.
          await bot._closeSeasonAndAnnounce(season, { adminId: `auto:${reason}` });
        } else {
          // Task #419 — strict all-or-nothing: if the bot isn't connected we
          // CAN'T announce, so we MUST NOT archive. Treat as a hard failure
          // and alert the owner; the next per-minute tick will retry once
          // the bot reconnects.
          throw new Error('Discord bot unavailable — refusing to roll over without announcement (per all-or-nothing contract).');
        }
      } catch (e) {
        console.error(`[Season] Auto-rollover failed for ${season.name}:`, e.message);
        await _alertOwnerOfRolloverFailure(season, e, bot);
      }
    }
  } catch (e) {
    console.warn('[Season] Rollover tick error:', e.message);
  } finally {
    _seasonRolloverInFlight = false;
  }
}
// First tick 90 s after boot to let the Discord bot finish connecting, then
// every 60 s. .unref() so the timer doesn't keep Node alive during tests.
setTimeout(() => { _runSeasonRolloverTick('boot').catch(() => {}); }, 90_000).unref();
setInterval(() => { _runSeasonRolloverTick('cron').catch(() => {}); }, 60_000).unref();

