// Task #452 — fan out tournament check-in notifications. Pulls the tournaments
// whose "open" or "5-min reminder" signal is now due (claimed atomically in the
// DB so each fires exactly once), then DMs / web-pushes each recipient through
// the notify() helper, which applies the per-user `tournament_checkin`
// preference. Best-effort: per-recipient failures are logged but never abort
// the tick. Exported for tests.
function _fmtMinutes(min) {
  const m = Math.max(0, Math.round(Number(min) || 0));
  if (m % 60 === 0 && m >= 60) {
    const h = m / 60;
    return `${h} hour${h === 1 ? '' : 's'}`;
  }
  return `${m} minute${m === 1 ? '' : 's'}`;
}

async function _runCheckinNotifyTick() {
  const { opens, reminders } = await db.claimTournamentCheckinNotifications();
  for (const t of opens) {
    const url = `/tournaments/${t.tournament_id}`;
    const window = _fmtMinutes(t.checkin_offset_min);
    const title = 'Tournament check-in is open';
    const body = `Check-in for "${t.name}" is now open — confirm your spot within the next ${window}.`;
    for (const aid of (t.recipients || [])) {
      try {
        await notify(aid, 'tournament_checkin', {
          discord: { content: `🏁 **${title}** — ${body}\nCheck in here: ${(process.env.SITE_URL || '')}${url}` },
          push: { title, body, url, data: { kind: 'tournament_checkin_open', tournament_id: t.tournament_id } },
        });
      } catch (e) {
        console.warn('[swiss] check-in open notify failed:', e.message);
      }
    }
  }
  for (const t of reminders) {
    const url = `/tournaments/${t.tournament_id}`;
    const title = 'Tournament check-in closing soon';
    const body = `Check-in for "${t.name}" closes in 5 minutes — check in now or you'll be dropped from the bracket.`;
    for (const aid of (t.recipients || [])) {
      try {
        await notify(aid, 'tournament_checkin', {
          discord: { content: `⏰ **${title}** — ${body}\nCheck in here: ${(process.env.SITE_URL || '')}${url}` },
          push: { title, body, url, data: { kind: 'tournament_checkin_reminder', tournament_id: t.tournament_id } },
        });
      } catch (e) {
        console.warn('[swiss] check-in reminder notify failed:', e.message);
      }
    }
  }
  return { opens: opens.length, reminders: reminders.length };
}

// Task #543 — run the no-show DQ sweep and tell each dropped player they were
// removed for missing check-in. The sweep flips `checkin_dq_done = TRUE` and
// DELETEs the no-shows in one shot per tournament, so each removed account is
// surfaced exactly once and these DMs can never duplicate across ticks. Gated
// per-user by the same `tournament_checkin` preference as the open/reminder
// signals, so opt-outs are honoured. Best-effort: per-recipient failures are
// logged but never abort the tick. Exported for tests.
async function _runCheckinDqSweepTick() {
  const summaries = await db.sweepTournamentCheckInDqs();
  let notified = 0;
  for (const s of summaries) {
    const url = `/tournaments/${s.tournament_id}`;
    const title = 'Dropped from tournament';
    // Task #579 — if slots are still open (and the event hasn't started), tell
    // the dropped player they can reclaim their spot from the bracket link.
    const canReclaim = s.spots_available == null || s.spots_available > 0;
    const reclaimHint = canReclaim
      ? ` Spots are still open — you can reclaim yours from the bracket while the tournament hasn't started.`
      : '';
    const body = `You were removed from "${s.name}" because you didn't check in before the window closed.${reclaimHint}`;
    for (const aid of (s.removed_account_ids || [])) {
      try {
        await notify(aid, 'tournament_checkin', {
          discord: { content: `🚫 **${title}** — ${body}\nView the bracket: ${(process.env.SITE_URL || '')}${url}` },
          push: { title, body, url, data: { kind: 'tournament_checkin_dq', tournament_id: s.tournament_id } },
        });
        notified++;
      } catch (e) {
        console.warn('[swiss] check-in DQ notify failed:', e.message);
      }
    }
  }
  return { tournaments: summaries.length, notified };
}

// Task #453 — auto-pay tournament winners via Stripe Connect Express.
//
// `tournament_payouts` (Task #412) snapshots per-place amounts when an event
// completes; this turns each pending row into a real Stripe Transfer once the
// winner has a Connect account that can receive payouts. Best-effort and
// idempotent: rows already 'paid' are skipped, and a failed transfer is left
// retryable (status 'failed' with the Stripe error stored).
function _stripeForPayouts() {
  if (!process.env.STRIPE_SECRET_KEY) return null;
  try { return require('../observability/stripeClient').getStripe(); } catch (_) { return null; }
}

// Reconciliation guard: find any Stripe Transfer that was already created for
// this payout row. We tag every transfer with metadata.payout_id and a
// transfer_group of `tournament_<id>`, so we can look it up before ever
// creating another one. This is the definitive defence against double-paying:
// if a previous attempt succeeded at Stripe but failed to persist locally (or
// the idempotency window expired), we find the real transfer here instead of
// sending a second one.
async function _findExistingPayoutTransfer(stripe, row) {
  try {
    const list = await stripe.transfers.list({
      transfer_group: `tournament_${row.tournament_id}`,
      limit: 100,
    });
    return list.data.find(t => t.metadata?.payout_id === String(row.id)) || null;
  } catch (e) {
    // If we can't confirm, fail safe: signal "unknown" so the caller does NOT
    // create a new transfer (avoids double-pay when the list call is flaky).
    console.warn(`[TournamentPayout] reconciliation lookup failed for payout ${row.id}:`, e.message);
    return undefined;
  }
}

// Attempt a single payout row's transfer. Returns the updated row (or the
// original when nothing could be done).
//
// Financial-correctness invariants:
//  - A transfer that succeeds at Stripe is NEVER downgraded to 'failed' — a
//    local DB write failure leaves the row 'pending' so the sweep reconciles
//    it (and marks it 'paid') on the next pass, never re-sending money.
//  - Before creating any transfer we reconcile against Stripe; an existing
//    transfer for this payout id is reused rather than duplicated, so a retry
//    can never double-pay even if the prior attempt's DB write was lost.
async function _transferTournamentPayoutRow(row) {
  if (!row) return null;
  if (row.transfer_status === 'paid') return row;
  if (!(row.amount_cents > 0)) return row;
  const stripe = _stripeForPayouts();
  if (!stripe) return row; // payments not configured — leave pending

  const dest = await db.resolvePayoutDestination(row.account_id);
  if (!dest || !dest.payouts_enabled) {
    // Winner hasn't connected (or KYC incomplete) — leave pending so the
    // sweep retries automatically once they connect.
    return row;
  }

  // Reconcile first: never create a second transfer for a payout that Stripe
  // already paid. `undefined` means the lookup itself failed — bail without
  // creating, to stay fail-safe.
  const existing = await _findExistingPayoutTransfer(stripe, row);
  if (existing === undefined) return row;
  if (existing) {
    try {
      return await db.setTournamentPayoutTransfer(row.id, {
        status: 'paid', stripeTransferId: existing.id, error: null,
      });
    } catch (dbErr) {
      console.error(`[TournamentPayout] payout ${row.id} already transferred (${existing.id}) but DB write failed — will reconcile:`, dbErr.message);
      return row;
    }
  }

  // Step 1 — create the transfer (money movement). Stable idempotency key per
  // payout id guards against concurrent duplicate sends; the reconciliation
  // above guards against the cross-window / lost-write cases.
  let transfer;
  try {
    transfer = await stripe.transfers.create({
      amount: row.amount_cents,
      currency: (row.currency || 'aud').toLowerCase(),
      destination: dest.stripe_account_id,
      transfer_group: `tournament_${row.tournament_id}`,
      metadata: {
        purpose: 'tournament_payout',
        tournament_id: String(row.tournament_id),
        payout_id: String(row.id),
        account_id: String(row.account_id),
        place: String(row.place),
      },
    }, { idempotencyKey: `tourpay_${row.id}` });
  } catch (err) {
    // Genuine failure — no money moved. Safe to mark 'failed' for retry.
    const msg = err?.message || String(err);
    console.warn(`[TournamentPayout] transfer failed for payout ${row.id}:`, msg);
    try {
      return await db.setTournamentPayoutTransfer(row.id, { status: 'failed', error: msg.slice(0, 500) });
    } catch (_) {
      return row;
    }
  }

  // Step 2 — money has moved. From here we must NEVER report 'failed'. If the
  // DB write fails, leave the row 'pending'; the next sweep's reconciliation
  // will find this transfer and mark it 'paid'.
  try {
    return await db.setTournamentPayoutTransfer(row.id, {
      status: 'paid', stripeTransferId: transfer.id, error: null,
    });
  } catch (dbErr) {
    console.error(`[TournamentPayout] transfer ${transfer.id} succeeded but DB write failed for payout ${row.id} — will reconcile on next sweep:`, dbErr.message);
    return row;
  }
}

// Settle every pending/failed payout for a tournament that can be paid now.
// `notifyPaid` (default true) sends the Task #582 paid-receipt the moment any
// row transitions to 'paid' so the winner hears about it immediately on the
// finalize / "Pay winners" paths — the background sweep passes `false` and
// fires a single end-of-sweep receipt pass instead to avoid redundant scans.
async function _settleTournamentPayouts(tournamentId, { includeFailed = false, notifyPaid = true } = {}) {
  const rows = await db.getPendingTournamentPayouts(tournamentId);
  const out = { attempted: 0, paid: 0, failed: 0, awaiting: 0 };
  for (const row of rows) {
    if (row.transfer_status === 'failed' && !includeFailed) { out.awaiting++; continue; }
    out.attempted++;
    const updated = await _transferTournamentPayoutRow(row);
    if (updated?.transfer_status === 'paid') out.paid++;
    else if (updated?.transfer_status === 'failed') out.failed++;
    else out.awaiting++;
  }
  // Immediately receipt any winner just paid (one-shot via `paid_notified_at`,
  // so this can never double-send with the background sweep). Best-effort.
  if (notifyPaid && out.paid > 0) {
    try { await _notifyPaidPayoutWinners(); }
    catch (e) { console.warn('[TournamentPayout] paid-receipt on settle:', e.message); }
  }
  return out;
}

// Task #545 — proactively nudge winners with an unclaimed prize to connect a
// payout account. A pending payout whose winner has no payout-ready Connect
// account would otherwise sit forever unless they happen to open the
// tournament page (where the "Connect payout account" CTA lives). We DM /
// web-push each such winner exactly once (the DB stamp `connect_notified_at`
// is the one-shot guard) and gate it per-user by the `tournament_payout_pending`
// preference. Best-effort: per-recipient failures are logged but never abort
// the sweep, and we only stamp after a successful send so a transient failure
// is retried on the next sweep. Exported for tests.
// Shared per-recipient send for both the first connect nudge and the Task #581
// follow-up reminder. `reminder` only changes the copy; both fire the same
// `tournament_payout_pending` event (so the same notification preference gates
// them) with the same push `kind`.
async function _sendPayoutConnectNudge(row, { reminder = false } = {}) {
  const url = `/tournaments/${row.tournament_id}`;
  const amount = (Number(row.amount_cents) || 0) / 100;
  const ccy = (row.currency || 'aud').toUpperCase();
  const prize = `${ccy} $${amount.toFixed(2)}`;
  const title = reminder
    ? 'Reminder: connect a payout account to claim your prize'
    : 'Connect a payout account to claim your prize';
  const body = reminder
    ? `Your ${prize} prize from "${row.tournament_name}" is still unclaimed — connect a payout account to receive it before it's too late.`
    : `You won ${prize} in "${row.tournament_name}" but we can't pay you yet — connect a payout account to receive it.`;
  await notify(row.account_id, 'tournament_payout_pending', {
    discord: { content: `💰 **${title}** — ${body}\nConnect here: ${(process.env.SITE_URL || '')}${url}` },
    push: { title, body, url, data: { kind: 'tournament_payout_pending', tournament_id: row.tournament_id } },
  });
}

async function _notifyUnconnectedPayoutWinners() {
  let notified = 0;
  let rows;
  try {
    rows = await db.getPayoutsNeedingConnectNotification();
  } catch (e) {
    console.warn('[TournamentPayout] connect-nudge query failed:', e.message);
    return { notified: 0 };
  }
  for (const row of (rows || [])) {
    try {
      await _sendPayoutConnectNudge(row, { reminder: false });
      // Stamp only after a successful send so a transient failure retries.
      await db.markTournamentPayoutConnectNotified(row.id);
      notified++;
    } catch (e) {
      console.warn('[TournamentPayout] connect-nudge notify failed:', e.message);
    }
  }
  return { notified };
}

// Task #581 — one bounded follow-up reminder for winners who got the first
// connect nudge `PAYOUT_CONNECT_REMINDER_DELAY_DAYS` ago (default 7) and are
// still pending + unconnected. Stamps `connect_renotified_at` after a successful
// send so each winner is reminded at most once — the anti-spam guard from
// Task #545 is preserved (we never re-clear `connect_notified_at`). Gated by the
// same `tournament_payout_pending` preference. Exported for tests.
const PAYOUT_CONNECT_REMINDER_DELAY_DAYS = (() => {
  const n = parseInt(process.env.PAYOUT_CONNECT_REMINDER_DELAY_DAYS, 10);
  return Number.isFinite(n) && n > 0 ? n : 7;
})();
async function _remindUnconnectedPayoutWinners() {
  let notified = 0;
  let rows;
  try {
    rows = await db.getPayoutsNeedingConnectReminder(PAYOUT_CONNECT_REMINDER_DELAY_DAYS);
  } catch (e) {
    console.warn('[TournamentPayout] connect-reminder query failed:', e.message);
    return { notified: 0 };
  }
  for (const row of (rows || [])) {
    try {
      await _sendPayoutConnectNudge(row, { reminder: true });
      // Stamp only after a successful send so a transient failure retries.
      await db.markTournamentPayoutConnectReminded(row.id);
      notified++;
    } catch (e) {
      console.warn('[TournamentPayout] connect-reminder notify failed:', e.message);
    }
  }
  return { notified };
}

// Task #582 — send a winner a one-shot receipt the moment their prize transfer
// lands ('paid'). Mirrors the connect-nudge fan-out: gated per-user by the
// `tournament_payout_paid` notification preference, stamped only after a
// successful send (`paid_notified_at`) so retries/sweeps never re-send, and
// best-effort (per-recipient failures are logged, never abort the sweep). The
// receipt links to the winner's payout history card on their own profile.
async function _sendPayoutPaidReceipt(row) {
  const url = `/player/${row.account_id}#my-payouts`;
  const amount = (Number(row.amount_cents) || 0) / 100;
  const ccy = (row.currency || 'aud').toUpperCase();
  const prize = `${ccy} $${amount.toFixed(2)}`;
  const title = 'Your prize has been paid';
  const body = `Your ${prize} prize from "${row.tournament_name}" has landed in your connected payout account.`;
  // Task #615 — give the winner a way to flag a payout that never actually
  // reached their bank (Stripe transfer succeeded but the downstream payout
  // bounced). The link drops them on their payout-history card where the
  // "Report a payment problem" control lives.
  const reportHint = "Didn't receive it? Open your payout history to report a payment problem.";
  await notify(row.account_id, 'tournament_payout_paid', {
    discord: { content: `🏆 **${title}** — ${body}\n${reportHint}\nSee your payout history: ${(process.env.SITE_URL || '')}${url}` },
    push: { title, body: `${body} ${reportHint}`, url, data: { kind: 'tournament_payout_paid', tournament_id: row.tournament_id } },
  });
}

async function _notifyPaidPayoutWinners() {
  let notified = 0;
  let rows;
  try {
    rows = await db.getPayoutsNeedingPaidReceipt();
  } catch (e) {
    console.warn('[TournamentPayout] paid-receipt query failed:', e.message);
    return { notified: 0 };
  }
  for (const row of (rows || [])) {
    try {
      await _sendPayoutPaidReceipt(row);
      // Stamp only after a successful send so a transient failure retries.
      await db.markTournamentPayoutPaidNotified(row.id);
      notified++;
    } catch (e) {
      console.warn('[TournamentPayout] paid-receipt notify failed:', e.message);
    }
  }
  return { notified };
}

// Background settlement sweep — pays winners who connected an account after
// the snapshot was taken. Pending-only (never auto-retries a hard failure, to
// avoid hammering Stripe with a doomed transfer); admins retry failures
// explicitly. First run 2 min after boot, then every 10 min.
let _tournamentPayoutSweepInFlight = false;
async function _runTournamentPayoutSweep(reason = 'cron') {
  if (_tournamentPayoutSweepInFlight) return;
  if (!process.env.STRIPE_SECRET_KEY) return;
  _tournamentPayoutSweepInFlight = true;
  try {
    const ids = await db.getTournamentsWithPendingPayouts();
    for (const tid of ids) {
      try { await _settleTournamentPayouts(tid, { includeFailed: false, notifyPaid: false }); }
      catch (e) { console.warn(`[TournamentPayout] sweep failed for ${tid}:`, e.message); }
    }
    // Receipt any payout that has just landed ('paid') — one-shot per payout.
    try { await _notifyPaidPayoutWinners(); }
    catch (e) { console.warn('[TournamentPayout] paid-receipt sweep error:', e.message); }
    // After settling, any payout still pending belongs to a winner without a
    // payout-ready account — prompt them (one-shot) to connect one.
    try { await _notifyUnconnectedPayoutWinners(); }
    catch (e) { console.warn('[TournamentPayout] connect-nudge sweep error:', e.message); }
    // Then re-nudge winners who ignored the first prompt long enough ago.
    try { await _remindUnconnectedPayoutWinners(); }
    catch (e) { console.warn('[TournamentPayout] connect-reminder sweep error:', e.message); }
  } catch (e) {
    console.warn('[TournamentPayout] sweep error:', e.message);
  } finally {
    _tournamentPayoutSweepInFlight = false;
  }
}
setTimeout(() => { _runTournamentPayoutSweep('boot').catch(() => {}); }, 2 * 60_000).unref();
setInterval(() => { _runTournamentPayoutSweep('cron').catch(() => {}); }, 10 * 60 * 1000).unref();

