        sort:     req.query.sort ? String(req.query.sort).slice(0, 16) : 'date',
        sortDir:  req.query.dir === 'asc' ? 'asc' : 'desc',
        limit:    Math.min(parseInt(req.query.limit || '50', 10) || 50, 200),
