  // ─── Task #412 — Tournament v2: Swiss, check-ins, per-place splits ─────
  // Shared tenant-scope guard for every new tournament v2 endpoint. Mirrors
  // the pattern at the top of /tournaments/:id (Task #333). Returns the
  // tournament row when visible to the caller, otherwise sends a 404 and
  // returns null so the route handler can short-circuit.
  async function _t412RequireScopedTournament(req, res) {
    const t = await db.getTournamentById(req.params.id);
    if (!t || !_visibleInScope(t, _resolveScopeTenantId(req))) {
      res.status(404).json({ error: 'Tournament not found' });
      return null;
    }
    return t;
  }

  router.get('/tournaments/:id/standings', async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const rows = await db.getSwissStandings(req.params.id);
      res.json({ standings: rows });
    } catch (err) {
      console.error('[API] tournament standings:', err.message);
      res.status(500).json({ error: 'Failed to fetch standings' });
    }
  });

  router.get('/tournaments/:id/checkins', async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const rows = await db.getTournamentCheckIns(req.params.id);
      res.json({ checkins: rows });
    } catch (err) {
      res.status(500).json({ error: 'Failed to fetch check-ins' });
    }
  });

  router.post('/tournaments/:id/checkin', express.json(), async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const rows = await db.checkInTournamentParticipant(req.params.id, accountId);
      res.json({ ok: true, checkins: rows });
    } catch (err) {
      res.status(400).json({ error: err.message });
    }
  });

  router.post('/tournaments/:id/advance-swiss-round', requireSuperuser, async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const matches = await db.advanceSwissRound(req.params.id);
      res.json({ ok: true, matches });
    } catch (err) {
      res.status(400).json({ error: err.message });
    }
  });

  router.get('/tournaments/:id/prize-splits', async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const splits = await db.getTournamentPrizeSplits(req.params.id);
      res.json({ splits });
    } catch (err) {
      res.status(500).json({ error: 'Failed to fetch prize splits' });
    }
  });

  router.put('/tournaments/:id/prize-splits', requireSuperuser, express.json(), async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const splits = await db.setTournamentPrizeSplits(req.params.id, req.body?.splits);
      res.json({ ok: true, splits });
    } catch (err) {
      res.status(400).json({ error: err.message });
    }
  });

  router.get('/tournaments/:id/payouts', async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const payouts = await db.getTournamentPayouts(req.params.id);
      res.json({ payouts });
    } catch (err) {
      res.status(500).json({ error: 'Failed to fetch payouts' });
    }
  });

  router.post('/tournaments/:id/finalize-payouts', requireSuperuser, async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const payouts = await db.finalizeTournamentPayouts(req.params.id);
      // Task #453 — immediately attempt to pay any winners who already have a
      // connected account; the rest stay pending for the background sweep.
      let settlement = null;
      try { settlement = await _settleTournamentPayouts(req.params.id, { includeFailed: false }); }
      catch (e) { console.warn('[TournamentPayout] settle-on-finalize:', e.message); }
      const updated = await db.getTournamentPayouts(req.params.id);
      res.json({ ok: true, payouts: updated, settlement });
    } catch (err) {
      res.status(400).json({ error: err.message });
    }
  });

  // Task #453 — settle all pending (and optionally failed) transfers for a
  // tournament. Superuser-only; drives the "Pay winners" button.
  router.post('/tournaments/:id/payouts/transfer', requireSuperuser, async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const includeFailed = req.body?.includeFailed === true || req.body?.includeFailed === 'true';
      const settlement = await _settleTournamentPayouts(req.params.id, { includeFailed });
      const payouts = await db.getTournamentPayouts(req.params.id);
      res.json({ ok: true, settlement, payouts });
    } catch (err) {
      res.status(400).json({ error: err.message });
    }
  });

  // Task #453 — retry a single failed payout transfer. Superuser-only.
  router.post('/tournaments/:id/payouts/:payoutId/retry', requireSuperuser, async (req, res) => {
    try {
      if (!(await _t412RequireScopedTournament(req, res))) return;
      const row = await db.getTournamentPayoutRow(req.params.payoutId);
      if (!row || String(row.tournament_id) !== String(parseInt(req.params.id))) {
        return res.status(404).json({ error: 'Payout not found' });
      }
      if (row.transfer_status === 'paid') {
        return res.json({ ok: true, alreadyPaid: true, payout: row });
      }
      const updated = await _transferTournamentPayoutRow(row);
      // Task #582 — receipt the winner immediately if this retry succeeded
      // (one-shot via `paid_notified_at`, safe alongside the background sweep).
      if (updated?.transfer_status === 'paid') {
        try { await _notifyPaidPayoutWinners(); }
        catch (e) { console.warn('[TournamentPayout] paid-receipt on retry:', e.message); }
      }
      res.json({ ok: updated?.transfer_status === 'paid', payout: updated });
    } catch (err) {
      res.status(400).json({ error: err.message });
    }
  });

  // Task #412 — sweep no-show DQs every 60s. Task #543 — and DM / push each
  // dropped player so the removal isn't silent.
  if (!global.__t412_checkin_sweep) {
    global.__t412_checkin_sweep = setInterval(() => {
      _runCheckinDqSweepTick().catch(err => {
        console.error('[swiss] check-in DQ sweep:', err.message);
      });
    }, 60 * 1000);
    if (global.__t412_checkin_sweep.unref) global.__t412_checkin_sweep.unref();
  }

  // Task #452 — notify registered players when their tournament check-in
  // window opens, then send a 5-minute-before-close reminder to anyone who
  // hasn't checked in. Both signals are one-shot per tournament (claimed
  // atomically in the DB) and gated per-user by the `tournament_checkin`
  // notification preference. Runs on the same 60s cadence as the DQ sweep.
  if (!global.__t452_checkin_notify) {
    global.__t452_checkin_notify = setInterval(() => {
      _runCheckinNotifyTick().catch(err => {
        console.error('[swiss] check-in notify tick:', err.message);
      });
    }, 60 * 1000);
    if (global.__t452_checkin_notify.unref) global.__t452_checkin_notify.unref();
  }

  // ---------- F6: MVP / attitude analytics ----------
  router.get('/player/:id/mvp-attitude-trends', async (req, res) => {
    try {
      if (!(await _flagOn('mvp_attitude_analytics', req))) return res.status(404).json({ error: 'Not found' });
      const win = Math.max(3, Math.min(parseInt(req.query.window) || 10, 50));
      const data = await db.getMvpAttitudeTrends(req.params.id, win);
      res.json(data);
    } catch (err) {
      console.error('[API] mvp-attitude-trends:', err.message);
      res.status(500).json({ error: 'Failed to fetch MVP/attitude trends' });
    }
  });

  // ---------- F7: Web push ----------
  router.get('/web-push/public-key', async (req, res) => {
    if (!(await _flagOn('web_push', req))) return res.status(404).json({ error: 'Not found' });
    if (!process.env.VAPID_PUBLIC_KEY) return res.status(503).json({ error: 'Web push not configured' });
    res.json({ publicKey: process.env.VAPID_PUBLIC_KEY });
  });

  router.post('/me/push/subscribe', express.json(), async (req, res) => {
    try {
      if (!(await _flagOn('web_push', req))) return res.status(404).json({ error: 'Not found' });
      if (!_webPushReady()) return res.status(503).json({ error: 'Web push not configured' });
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const sub = req.body?.subscription;
      if (!sub?.endpoint || !sub?.keys?.p256dh || !sub?.keys?.auth) {
        return res.status(400).json({ error: 'Invalid PushSubscription payload' });
      }
      await db.addPushSubscription({
        accountId,
        endpoint: sub.endpoint,
        p256dh: sub.keys.p256dh,
        auth: sub.keys.auth,
        userAgent: req.headers['user-agent'] || null,
      });
      res.json({ ok: true });
    } catch (err) {
      console.error('[API] push/subscribe:', err.message);
      res.status(500).json({ error: err.message });
    }
  });

  router.post('/me/push/test', express.json(), async (req, res) => {
    try {
      if (!(await _flagOn('web_push', req))) return res.status(404).json({ error: 'Not found' });
      if (!_webPushReady()) return res.status(503).json({ error: 'Web push not configured' });
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const subs = await db.getPushSubscriptionsForAccount(accountId);
      if (!subs.length) return res.status(404).json({ error: 'No push subscriptions for this account' });
      const payload = JSON.stringify({
        title: 'Dota 2 Inhouse — Test push',
        body: 'Push notifications are working. You can manage these in /settings/notifications.',
        url: '/',
      });
      let sent = 0;
      for (const s of subs) {
        try {
          await webpush.sendNotification(
            { endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } },
            payload
          );
          await db.touchPushSubscription(s.endpoint);
          sent++;
        } catch (err) {
          // 410 / 404 = subscription expired → drop it.
          if (err && (err.statusCode === 404 || err.statusCode === 410)) {
            await db.removePushSubscriptionByEndpoint(s.endpoint).catch(() => {});
          }
        }
      }
      res.json({ ok: true, sent });
    } catch (err) {
      console.error('[API] push/test:', err.message);
      res.status(500).json({ error: err.message });
    }
  });

  // ---------- Task #381: Expo push tokens (mobile companion app) ----------
  // Register or refresh the signed-in user's Expo push token. Tokens look
  // like `ExponentPushToken[xxxxxxxxxxxx]`. We deliberately do NOT gate
  // this behind the `web_push` feature flag — the mobile app is its own
  // surface and ships independently — but it does require a valid session
  // (the user must have completed Steam OpenID via the in-app browser).
  router.post('/me/expo-push/register', express.json(), async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const token = typeof req.body?.token === 'string' ? req.body.token.trim() : '';
      // Loose validation — Expo tokens are bracketed strings. We don't try
      // to police the exact format because Expo's spec allows both
      // ExponentPushToken[...] and ExpoPushToken[...] variants.
      if (!token || token.length < 10 || token.length > 200) {
        return res.status(400).json({ error: 'Invalid Expo push token' });
      }
      const platform = ['ios', 'android'].includes(req.body?.platform) ? req.body.platform : null;
      const appVersion = typeof req.body?.app_version === 'string'
        ? req.body.app_version.slice(0, 32) : null;
      const deviceLabel = typeof req.body?.device_label === 'string'
        ? req.body.device_label.slice(0, 64) : null;
      await db.addExpoPushToken({ accountId, token, platform, appVersion, deviceLabel });
      res.json({ ok: true });
    } catch (err) {
      console.error('[API] expo-push/register:', err.message);
      res.status(500).json({ error: err.message });
    }
  });

  router.post('/me/expo-push/unregister', express.json(), async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const token = typeof req.body?.token === 'string' ? req.body.token.trim() : '';
      if (!token) return res.status(400).json({ error: 'token required' });
      // Only allow deleting tokens that belong to this account so a
      // hostile client can't kick another user's device off push.
      const owned = await db.getExpoPushTokensForAccount(accountId);
      if (!owned.some(t => t.token === token)) {
        return res.status(404).json({ error: 'Unknown token for this account' });
      }
      await db.removeExpoPushToken(token);
      res.json({ ok: true });
    } catch (err) {
      console.error('[API] expo-push/unregister:', err.message);
      res.status(500).json({ error: err.message });
    }
  });

  router.post('/me/expo-push/test', express.json(), async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const tokens = await db.getExpoPushTokensForAccount(accountId);
      if (!tokens.length) return res.status(404).json({ error: 'No Expo push tokens for this account' });
      const result = await _fanOutExpoPush(accountId, {
        title: 'OCE Inhouse — Test push',
        body: 'Mobile push notifications are working. Manage these in Settings.',
        url: '/',
      });
      res.json({ ok: true, ...result });
    } catch (err) {
      console.error('[API] expo-push/test:', err.message);
      res.status(500).json({ error: err.message });
    }
  });

  // ---------- Vanity slugs + Profile Spotlight (Task #208 / v6.64) ----------
  // Reserved-path deny-list for `/p/<slug>`. Anything that collides with a
  // current top-level route (App.jsx Routes) or a near-miss must NOT be
  // claimable — otherwise `/p/admin` could be confused for `/admin`. Keep
  // this in sync with the App.jsx `<Route path>` list.
  const RESERVED_VANITY_SLUGS = new Set([
    'api', 'admin', 'p', 'player', 'players', 'match', 'matches', 'heroes',
    'leaderboard', 'stats', 'positions', 'synergy', 'upload', 'seasons',
    'predictions', 'patch-notes', 'pickem', 'sponsorships', 'multikills',
    'ward-map', 'records', 'pudge-stats', 'schedule', 'inhouse', 'social',
    'player-network', 'benchmarks', 'insights', 'tournaments',
    'weekend-tournament', 'hall-of-fame', 'join', 'settings', 'pro',
    'coaches', 'shop', 'cosmetics', 'my-bookings', 'buyin-success',
    'player-tools', 'head-to-head', 'compare', 'draft', 'draft-assistant',
    'draft-stats', 'hero-breakdown', 'hero-position-meta',
    'position-player-profiles', 'season-summary', 'embed', 'static',
    'auth', 'login', 'logout', 'signin', 'signout', 'register', 'about',
    'help', 'support', 'terms', 'privacy', 'contact', 'faq', 'news',
    'blog', 'home', 'dashboard', 'search', 'notifications', 'billing',
    'me', 'us', 'spotlight', 'featured', 'undefined', 'null', 'true',
    'false', 'root', 'system',
  ]);

  function _vanitySlugIsReserved(slug) {
    return RESERVED_VANITY_SLUGS.has(String(slug || '').toLowerCase());
  }

  // Public availability probe for the Settings/Cosmetics picker. Always
  // 200; the body says whether the slug is claimable + why not.
  router.get('/vanity-slug/availability', async (req, res) => {
    try {
      const slug = req.query.slug || '';
      if (!db.isWellFormedVanitySlug(slug)) {
        return res.json({
          slug: String(slug || '').toLowerCase(),
          available: false,
          reason: 'invalid',
        });
      }
      if (_vanitySlugIsReserved(slug)) {
        return res.json({
          slug: String(slug).toLowerCase(),
          available: false,
          reason: 'reserved',
        });
      }
      const accountId = req.session?.accountId || null;
      const r = await db.isVanitySlugAvailable(slug, accountId);
      res.json({ slug: String(slug).toLowerCase(), ...r });
    } catch (err) {
      console.error('[API] vanity-slug/availability:', err.message);
      res.status(500).json({ error: 'availability check failed' });
    }
  });

  // Task #221 — Public read of any player's currently-claimed vanity slug,
  // so the profile page's Share button can copy the short `/p/<slug>` URL
  // when one exists. Returns `{ slug: null }` for unclaimed accounts so
  // the client can fall back to the canonical `/player/<id>` URL without
  // a 404. No auth required — slugs are already public via `/p/<slug>`.
  router.get('/player/:id/vanity-slug', async (req, res) => {
    try {
      const cur = await db.getVanitySlugByAccount(req.params.id).catch(() => null);
      res.set('Cache-Control', 'public, max-age=60');
      res.json({ slug: cur?.slug || null });
    } catch (err) {
      console.error('[API] player/:id/vanity-slug:', err.message);
      res.status(500).json({ error: 'Failed to load vanity slug' });
    }
  });

  // Task #740 — helper: account has vanity URL access via Stripe perk OR coin purchase.
  async function _hasVanityUrlPerk(accountId) {
    if (!accountId) return false;
    const [fromStripe, fromCoins] = await Promise.all([
      db.magV3.hasOneOffPerk(accountId, 'cosmetic:vanity_url'),
      db.hasCoinCosmetic(accountId, 'cosmetic', 'vanity_url'),
    ]);
    return fromStripe || fromCoins;
  }

  router.get('/me/vanity-slug', async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const [cur, hasPerk] = await Promise.all([
        db.getVanitySlugByAccount(accountId),
        _hasVanityUrlPerk(accountId),
      ]);
      // Task #740: Custom URL is a paid cosmetic — Pro no longer bundles it.
      // Access tiers:
      //   1. Purchased perk (Stripe or coins) → full access, can claim/change/release.
      //   2. Existing slug (grandfathered from the era it was bundled with Pro)
      //      → full management of that slug (claim new value, release); purchasing
      //      the add-on is optional. Cannot claim a brand-new slug from scratch
      //      without purchasing — but since they already hold one, claiming a new
      //      value is effectively a "change", which is allowed.
      //   3. No perk, no slug → must purchase.
      const hasSlug = !!(cur?.slug && !cur?.released_at);
      const can_claim = hasPerk || hasSlug;
      const grandfathered = hasSlug && !hasPerk;
      res.json({
        slug: cur?.slug || null,
        released_at: cur?.released_at || null,
        has_perk: hasPerk,
        can_claim,
        grandfathered,
        cooldown_days: 30,
      });
    } catch (err) {
      console.error('[API] me/vanity-slug GET:', err.message);
      res.status(500).json({ error: 'Failed to load vanity slug' });
    }
  });

  router.post('/me/vanity-slug', express.json(), async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const [cur, hasPerk] = await Promise.all([
        db.getVanitySlugByAccount(accountId),
        _hasVanityUrlPerk(accountId),
      ]);
      const hasSlug = !!(cur?.slug && !cur?.released_at);
      if (!hasPerk && !hasSlug) {
        return res.status(403).json({ error: 'Custom URL requires the Custom URL add-on. Buy it in the shop.' });
      }
      const slug = String(req.body?.slug || '').trim().toLowerCase();
      if (!db.isWellFormedVanitySlug(slug)) {
        return res.status(400).json({ error: 'Invalid slug. 3–24 chars, lowercase a–z, 0–9, hyphen.' });
      }
      if (_vanitySlugIsReserved(slug)) {
        return res.status(409).json({ error: 'That slug is reserved.' });
      }
      try {
        const r = await db.claimVanitySlug(accountId, slug);
        return res.json({ slug: r.slug, ok: true });
      } catch (err) {
        if (err.code === 'SLUG_TAKEN') return res.status(409).json({ error: 'That slug is taken.' });
        if (err.code === 'SLUG_COOLDOWN') return res.status(409).json({ error: 'That slug was recently released. Cooldown is active.' });
        throw err;
      }
    } catch (err) {
      console.error('[API] me/vanity-slug POST:', err.message);
      res.status(500).json({ error: 'Failed to claim slug' });
    }
  });

  router.delete('/me/vanity-slug', async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const [cur, hasPerk] = await Promise.all([
        db.getVanitySlugByAccount(accountId),
        _hasVanityUrlPerk(accountId),
      ]);
      // Both purchased-perk holders and grandfathered holders can release.
      // (If you have no slug there is nothing to release anyway.)
      const hasSlug = !!(cur?.slug && !cur?.released_at);
      if (!hasPerk && !hasSlug) {
        return res.status(403).json({ error: 'No active slug to release.' });
      }
      const r = await db.releaseVanitySlug(accountId);
      res.json({ ok: true, ...r });
    } catch (err) {
      console.error('[API] me/vanity-slug DELETE:', err.message);
      res.status(500).json({ error: 'Failed to release slug' });
    }
  });

  // Task #740 — Shop: Custom URL Stripe checkout. Uses the admin-editable
  // economy price (vanity_url_cents) and the existing one-off perk webhook.
  router.post('/shop/vanity-url/stripe-checkout', express.json(), async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      if (await _hasVanityUrlPerk(accountId)) {
        return res.status(409).json({ error: 'You already own the Custom URL add-on.' });
      }
      if (!stripe) return res.status(503).json({ error: 'Payments are not configured.' });
      const overrides = await _getEconOverrides();
      const priceCents = _econInt(overrides, 'vanity_url_cents');
      const proto = (req.headers['x-forwarded-proto'] || req.protocol || 'https').split(',')[0].trim();
      const host = req.headers['x-forwarded-host'] || req.headers.host;
      const baseUrl = `${proto}://${host}`;
      const session = await stripe.checkout.sessions.create({
        mode: 'payment',
        payment_method_types: ['card'],
        line_items: [{
          price_data: {
            currency: 'aud',
            product_data: { name: 'Custom Profile URL — OCE Inhouse' },
            unit_amount: priceCents,
          },
          quantity: 1,
        }],
        success_url: `${baseUrl}/shop?vanity_success=1`,
        cancel_url: `${baseUrl}/shop`,
        metadata: {
          purpose: 'one_off_perk',
          account_id: String(accountId),
          perk_key: 'cosmetic:vanity_url',
        },
      });
      await db.magV3.createOneOffPerkPending({
        accountId,
        perkKey: 'cosmetic:vanity_url',
        stripeSessionId: session.id,
        amountCents: priceCents,
        currency: 'aud',
        metadata: { name: 'Custom Profile URL — OCE Inhouse' },
      });
      res.json({ url: session.url });
    } catch (err) {
      console.error('[API] shop/vanity-url/stripe-checkout:', err.message);
      res.status(500).json({ error: err.message || 'Failed to create checkout' });
    }
  });

  // Task #740 — effective prices for the Custom URL shop card (public read).
  router.get('/shop/vanity-url/price', async (req, res) => {
    try {
      const overrides = await _getEconOverrides();
      const coinPrices = await _getEffectiveCoinPrices();
      res.json({
        stripe_cents: _econInt(overrides, 'vanity_url_cents'),
        coin_price: coinPrices['cosmetic:vanity_url'],
      });
    } catch (err) {
      res.status(500).json({ error: 'Failed to load prices' });
    }
  });

  // ----- Profile Spotlight -----
  // Public read, cached 60s in-memory so a hot home page doesn't hammer PG.
  let _spotlightCache = { value: undefined, expiresAt: 0 };
  function _invalidateSpotlightCache() { _spotlightCache = { value: undefined, expiresAt: 0 }; }

  router.get('/spotlight/current', async (req, res) => {
    try {
      const now = Date.now();
      if (_spotlightCache.value !== undefined && _spotlightCache.expiresAt > now) {
        res.set('Cache-Control', 'public, max-age=60');
        return res.json(_spotlightCache.value);
      }
      const row = await db.getCurrentSpotlight();
      let payload;
      if (row) {
        // Fetch the player's most-played hero so the home card can show a
        // hero portrait alongside the spotlight (v7.10).
        let topHero = null;
        try {
          const pool = db.getPool();
          const heroRow = await pool.query(
            `SELECT hero_name FROM player_stats
             WHERE account_id = $1 AND hero_name IS NOT NULL AND hero_name != ''
             GROUP BY hero_name ORDER BY COUNT(*) DESC LIMIT 1`,
            [row.account_id]
          );
          topHero = heroRow.rows[0]?.hero_name || null;
        } catch (_) {}
        payload = {
          spotlight: {
            id: row.id,
            account_id: String(row.account_id),
            headline: row.headline,
            blurb: row.blurb,
            starts_at: row.starts_at,
            ends_at: row.ends_at,
            display_name: row.display_name || null,
            top_hero: topHero,
            // v6.76 / Task #222 — surface 'admin' vs 'auto' so the home page
            // card can show an "Auto-selected" pill instead of "spotlight".
            source: row.source || 'admin',
          },
        };
      } else {
        payload = { spotlight: null };
      }
      _spotlightCache = { value: payload, expiresAt: now + 60_000 };
      res.set('Cache-Control', 'public, max-age=60');
      res.json(payload);
    } catch (err) {
      console.error('[API] spotlight/current:', err.message);
      res.status(500).json({ error: 'Failed to load spotlight' });
    }
  });

  router.get('/admin/spotlight', requireSuperuser, async (req, res) => {
    try {
      const rows = await db.listSpotlights(100);
      res.set('Cache-Control', 'no-store');
      res.json({ spotlights: rows });
    } catch (err) {
      console.error('[API] admin/spotlight GET:', err.message);
      res.status(500).json({ error: 'Failed to list spotlights' });
    }
  });

  router.post('/admin/spotlight', requireSuperuser, express.json(), async (req, res) => {
    try {
      const body = req.body || {};
      const accountId = body.account_id;
      const headline = (body.headline || '').toString().trim();
      const blurb = body.blurb ? String(body.blurb).trim() : null;
      const startsAt = body.starts_at || null;
      const endsAt = body.ends_at || null;
      if (!accountId) return res.status(400).json({ error: 'account_id required' });
      if (!headline) return res.status(400).json({ error: 'headline required' });
      const row = await db.createSpotlight({
        accountId,
        headline,
        blurb,
        startsAt,
        endsAt,
        createdBy: req.session?.accountId ? `account:${req.session.accountId}` : 'superuser',
      });
      _invalidateSpotlightCache();
      res.json({ ok: true, spotlight: row });
    } catch (err) {
      // Overlap guard returns 409 so the admin UI can surface the
      // conflicting entry inline instead of a generic 500.
      if (err.code === 'SPOTLIGHT_OVERLAP') {
        return res.status(409).json({ error: err.message });
      }
      console.error('[API] admin/spotlight POST:', err.message);
      res.status(500).json({ error: err.message || 'Failed to create spotlight' });
    }
  });

  // PATCH /admin/spotlight/:id — edit a queued or active (not-yet-ended)
  // spotlight: headline, blurb, starts_at, ends_at. Same overlap guard
  // (excluding the row itself) applies.
  router.patch('/admin/spotlight/:id', requireSuperuser, express.json(), async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (!Number.isFinite(id)) return res.status(400).json({ error: 'invalid id' });
      const body = req.body || {};
      const row = await db.updateSpotlight(id, {
        headline: body.headline,
        blurb: body.blurb,
        startsAt: body.starts_at,
        endsAt: body.ends_at,
      });
      _invalidateSpotlightCache();
      res.json({ ok: true, spotlight: row });
    } catch (err) {
      if (err.code === 'SPOTLIGHT_OVERLAP') {
        return res.status(409).json({ error: err.message });
      }
      console.error('[API] admin/spotlight PATCH:', err.message);
      res.status(400).json({ error: err.message || 'Failed to update spotlight' });
    }
  });

  router.delete('/admin/spotlight/:id', requireSuperuser, async (req, res) => {
    try {
      const id = parseInt(req.params.id, 10);
      if (!Number.isFinite(id)) return res.status(400).json({ error: 'invalid id' });
      const ok = await db.deleteSpotlight(id);
      _invalidateSpotlightCache();
      res.json({ ok, deleted: ok });
    } catch (err) {
      console.error('[API] admin/spotlight DELETE:', err.message);
      res.status(500).json({ error: 'Failed to delete spotlight' });
    }
  });

  // ---------- Profile customization ----------
  // Pro-tier check (cached 60s; invalidated on Stripe webhook + checkout).
  async function _isProAccount(accountId) {
    if (!accountId) return false;
    const key = String(accountId);
    const now = Date.now();
    const cached = _proCache.get(key);
    if (cached && cached.expiresAt > now) return cached.value;
    const value = await db.isProMember(accountId).catch(() => false);
    _proCache.set(key, { value, expiresAt: now + 60_000 });
    return value;
  }

  // Task #205 — public live presence chip for /players/:id v3 cover.
  // Always returns 200 with a `{ status, ... }` payload so the cover never
  // breaks. Defaults to `offline` on any error, missing data, or visibility
  // opt-out. Polled client-side every 30s while the tab is visible.
  router.get('/players/:id/presence', async (req, res) => {
    try {
      const { getPlayerPresence } = require('../services/presenceService');
      const data = await getPlayerPresence(req.params.id);
      res.set('Cache-Control', 'no-store');
      res.json(data || { status: 'offline', updated_at: null });
    } catch (err) {
      res.json({ status: 'offline', updated_at: null });
    }
  });

  // Task #213 — bulk live-presence rollup powering the /players "Live now"
  // tab. One call returns every visible account whose presence is in_game,
  // in_lobby, in_queue, or in_voice — so the page renders without fanning
  // out N profile pings. Plain Discord-online is intentionally excluded
  // (the rollup is scoped to actively-doing-something statuses). Same
  // no-store + soft-fail semantics as the per-profile chip endpoint above.
  router.get('/presence/live', async (req, res) => {
    try {
      const { getAllLivePresences } = require('../services/presenceService');
      const rows = await getAllLivePresences();
      res.set('Cache-Control', 'no-store');
      res.json({ players: Array.isArray(rows) ? rows : [] });
    } catch (err) {
      res.json({ players: [] });
    }
  });

  // Task #227 — count-only fast path used by the global nav badge. Same
  // soft-fail semantics as /presence/live; the badge polls this every 30s
  // gated on document.visibilityState, so it must stay cheap and never
  // throw on the public path.
  router.get('/presence/live/count', async (req, res) => {
    try {
      const { getAllLivePresences } = require('../services/presenceService');
      const rows = await getAllLivePresences();
      res.set('Cache-Control', 'no-store');
      res.json({ count: Array.isArray(rows) ? rows.length : 0 });
    } catch (err) {
      res.json({ count: 0 });
    }
  });

  // Task #205 — visibility toggle for the live presence chip. Stored on
  // player_profiles.presence_visible (default TRUE). Same auth shape as
  // the other /me/* notification endpoints.
  router.get('/me/presence-visibility', async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const pool = db.getPool();
      const r = await pool.query(
        `SELECT presence_visible FROM player_profiles WHERE account_id = $1`,
        [String(accountId)]
      );
      const visible = r.rows.length === 0 ? true : r.rows[0].presence_visible !== false;
      res.json({ presence_visible: visible });
    } catch (err) {
      console.error('[API] presence-visibility GET:', err.message);
      res.status(500).json({ error: 'Failed to fetch presence visibility' });
    }
  });
  router.post('/me/presence-visibility', express.json(), async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const visible = req.body?.presence_visible !== false;
      const pool = db.getPool();
      await pool.query(
        `INSERT INTO player_profiles (account_id, presence_visible)
           VALUES ($1, $2)
         ON CONFLICT (account_id) DO UPDATE SET presence_visible = EXCLUDED.presence_visible, updated_at = NOW()`,
        [String(accountId), visible]
      );
      res.json({ presence_visible: visible });
    } catch (err) {
      console.error('[API] presence-visibility POST:', err.message);
      res.status(500).json({ error: 'Failed to update presence visibility' });
    }
  });

  router.get('/me/profile', async (req, res) => {
    try {
      const accountId = req.session?.accountId;
      if (!accountId) return res.status(401).json({ error: 'Sign in with Steam' });
      const customization = await db.getPlayerProfileCustomization(accountId);
      const isPro = await _isProAccount(accountId);
      // v6.63 / Task #207 — surface owned one-time entitlements (founders ring etc.)
      const owned_entitlements = await db.getOwnedEntitlements(accountId).catch(() => []);
      res.json({ customization: customization || null, is_pro: isPro, owned_entitlements });
    } catch (err) {
      console.error('[API] me/profile GET:', err.message);
      res.status(500).json({ error: 'Failed to fetch profile customization' });
    }
  });

  // "Live now" hub — inhouse players currently streaming on Twitch. Reads the
